package com.campus.personnel.application;
import java.time.Clock; import java.util.*; import com.campus.identity.application.IdentityUserDirectory; import com.campus.organization.application.OrganizationUnitManagementService; import com.campus.organization.domain.OrganizationUnitStatus; import com.campus.personnel.domain.*; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class FacultyStaffManagementService { private final FacultyStaffRepository members; private final OrganizationUnitManagementService organizations; private final IdentityUserDirectory identityUsers; private final Clock clock; private final com.campus.shared.application.PeopleRegistryAudit audits; public FacultyStaffManagementService(FacultyStaffRepository m,OrganizationUnitManagementService o,IdentityUserDirectory i,Clock c,com.campus.shared.application.PeopleRegistryAudit a){members=m;organizations=o;identityUsers=i;clock=c;audits=a;} @Transactional public FacultyStaffMember create(String n,String name,String email,UUID identityUserId,PersonnelType type,UUID unit,PersonnelStatus status){return create(null,n,name,email,identityUserId,type,unit,status);} @Transactional public FacultyStaffMember create(UUID actor,String n,String name,String email,UUID identityUserId,PersonnelType type,UUID unit,PersonnelStatus status){unit(unit);identity(identityUserId);FacultyStaffMember m;try{m=FacultyStaffMember.create(UUID.randomUUID(),n,name,email,identityUserId,type,unit,status==null?PersonnelStatus.ACTIVE:status,clock.instant());}catch(FacultyStaffMember.InvalidFacultyStaffMemberException e){throw new RequestValidationException();}if(members.existsByPersonnelNumber(m.personnelNumber()))throw new PersonnelNumberAlreadyExistsException();FacultyStaffMember saved;try{saved=members.save(m);}catch(DataIntegrityViolationException e){throw new PersonnelNumberAlreadyExistsException();}if(actor!=null)audits.record(actor,"FACULTY_STAFF",saved.id(),"CREATED",clock.instant());return saved;} @Transactional(readOnly=true) public FacultyStaffMember get(UUID id){return members.findById(id).orElseThrow(FacultyStaffNotFoundException::new);} @Transactional(readOnly=true) public List<FacultyStaffMember> list(){return members.findAll();} @Transactional(readOnly=true) public com.campus.shared.application.PageResult<FacultyStaffMember> search(FacultyStaffSearch search){return members.search(search);} @Transactional public FacultyStaffMember update(UUID id,String n,String name,String email,UUID identityUserId,PersonnelType type,UUID unit,PersonnelStatus status,long version){return update(null,id,n,name,email,identityUserId,type,unit,status,version);} @Transactional public FacultyStaffMember update(UUID actor,UUID id,String n,String name,String email,UUID identityUserId,PersonnelType type,UUID unit,PersonnelStatus status,long version){FacultyStaffMember old=get(id);unit(unit);identity(identityUserId);FacultyStaffMember next;try{next=new FacultyStaffMember(id,n,name,email,identityUserId,type,unit,status,old.rowVersion(),old.createdAt(),clock.instant());}catch(FacultyStaffMember.InvalidFacultyStaffMemberException e){throw new RequestValidationException();}FacultyStaffMember saved;try{saved=members.saveMutation(next,version);}catch(NoSuchElementException e){throw new FacultyStaffNotFoundException();}catch(DataIntegrityViolationException e){throw new PersonnelNumberAlreadyExistsException();}if(actor!=null)audits.record(actor,"FACULTY_STAFF",saved.id(),"UPDATED",clock.instant());return saved;} private void unit(UUID id){try{if(organizations.get(id).status()!=OrganizationUnitStatus.ACTIVE)throw new OrganizationUnitUnavailableException();}catch(OrganizationUnitManagementService.OrganizationUnitNotFoundException e){throw new OrganizationUnitUnavailableException();}} private void identity(UUID id){if(id!=null&&!identityUsers.exists(id))throw new IdentityUserUnavailableException();} public static final class FacultyStaffNotFoundException extends RuntimeException{} public static final class PersonnelNumberAlreadyExistsException extends RuntimeException{} public static final class ConcurrentFacultyStaffModificationException extends RuntimeException{} public static final class OrganizationUnitUnavailableException extends RuntimeException{} public static final class IdentityUserUnavailableException extends RuntimeException{} public static final class RequestValidationException extends RuntimeException{} }
